//! The factory loop templates (`data/loops/templates`, generated by
//! `scripts/gen_loop_templates.py`) against the live catalog — the loops design notes T6.
//!
//! Every model and every `fx.*` effect in `metal_graph::NodeKind::catalog` has
//! at least one template; every float a template names is one of that
//! model's own floats (not the camera, not a shared signal/effects float);
//! every palette slot exists and every palette set it names ships. The
//! catalog is walked, never counted by hand (plan rule 7). Effect loops'
//! Float tracks are checked against the effect's declared params (T11).

use std::collections::{BTreeMap, BTreeSet};
use std::path::{Path, PathBuf};

use metal_perform::pattern::{Library, TargetKind, TrackTarget};
use metal_schema::{Block, Manifest};

fn repo() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("../..")
}

fn manifest() -> Manifest {
    let text = std::fs::read_to_string(repo().join("data/schema.json")).expect("data/schema.json");
    Manifest::parse(&text).expect("schema parses")
}

fn library() -> Library {
    let user = std::env::temp_dir().join(format!("fw-templates-none-{}", std::process::id()));
    Library::load(&repo().join("data/loops/templates"), &user)
}

/// A model's own floats and colour slots: every block but the trailing
/// signal + effects floats and the effects' colour slot; never a camera.
fn own(schema: &metal_schema::Schema) -> (BTreeSet<&'static str>, BTreeSet<&'static str>) {
    let shared: BTreeSet<&str> = metal_schema::SIGNAL_FLOATS
        .iter()
        .chain(metal_schema::EFFECTS_FLOATS)
        .map(|s| s.name)
        .collect();
    let (mut floats, mut slots) = (BTreeSet::new(), BTreeSet::new());
    let n = schema.blocks.len();
    for b in &schema.blocks[..n.saturating_sub(3)] {
        match b {
            Block::Floats(specs) => floats.extend(
                specs
                    .iter()
                    .map(|s| s.name)
                    .filter(|n| !shared.contains(n) && !n.starts_with("cam_")),
            ),
            Block::ColorSlot(name, _) => {
                slots.insert(*name);
            }
            Block::Camera(_) => {}
        }
    }
    (floats, slots)
}

#[test]
fn factory_templates_load_clean_and_name_real_things() {
    let lib = library();
    assert!(lib.problems.is_empty(), "skipped templates: {:?}", lib.problems);
    assert!(lib.palettes().count() >= 4, "palette sets ship");

    let suite: BTreeMap<String, &'static metal_schema::Schema> =
        manifest().into_suite().into_iter().map(|e| (e.id, e.schema)).collect();
    let effects: BTreeSet<String> = metal_graph::NodeKind::catalog(&manifest())
        .into_iter()
        .filter_map(|k| k.kind.strip_prefix("fx.").map(str::to_string))
        .collect();

    for l in lib.loops() {
        l.validate().unwrap_or_else(|e| panic!("{}: {e}", l.id));
        assert!(!l.name.is_empty(), "{}: unnamed", l.id);
        match &l.target_kind {
            TargetKind::Model(m) => {
                let schema = suite.get(m).unwrap_or_else(|| panic!("{}: no model {m}", l.id));
                let (floats, slots) = own(schema);
                for t in &l.tracks {
                    match &t.target {
                        TrackTarget::Float { param } => assert!(
                            floats.contains(param.as_str()),
                            "{}: {param} is not one of {m}'s own floats",
                            l.id
                        ),
                        TrackTarget::Palette { slot, palette, .. } => {
                            assert!(slots.contains(slot.as_str()), "{}: {m} has no slot {slot}", l.id);
                            assert!(lib.palette(palette).is_some(), "{}: no palette {palette}", l.id);
                        }
                        TrackTarget::Amount => unreachable!("validate refuses it"),
                    }
                }
            }
            TargetKind::Effect(e) => {
                assert!(effects.contains(e), "{}: no effect fx.{e}", l.id);
                // T11: Float tracks name the effect's own float params (its
                // schema, `effect_params`); an Amount track only fits an
                // effect whose params are one amount.
                let params = metal_graph::params::effect_params(&format!("fx.{e}"));
                for t in &l.tracks {
                    match &t.target {
                        TrackTarget::Float { param } => assert!(
                            params
                                .iter()
                                .any(|p| &p.name == param && p.kind == metal_graph::params::ParamKind::Float),
                            "{}: fx.{e} has no float param {param}",
                            l.id
                        ),
                        TrackTarget::Amount => {
                            assert_eq!(params.len(), 1, "{}: fx.{e} has no single amount to loop", l.id)
                        }
                        TrackTarget::Palette { .. } => unreachable!("validate refuses it"),
                    }
                }
            }
        }
    }
}

#[test]
fn every_model_and_every_effect_in_the_catalog_has_a_template() {
    let lib = library();
    let mut missing = Vec::new();
    for k in metal_graph::NodeKind::catalog(&manifest()) {
        // `gen.ramp` is a source, not a model (rule 1): no model to loop.
        if k.kind == metal_graph::RAMP_KIND {
            continue;
        }
        let target = if let Some(m) = k.kind.strip_prefix("gen.") {
            TargetKind::Model(m.to_string())
        } else if let Some(e) = k.kind.strip_prefix("fx.") {
            TargetKind::Effect(e.to_string())
        } else {
            continue;
        };
        if lib.for_target(&target).next().is_none() {
            missing.push(k.kind);
        }
    }
    assert!(missing.is_empty(), "no factory template for: {missing:?}");
}

/// T11: every multi-parameter effect ships at least two templates that each
/// drive two or more of its params.
#[test]
fn multi_parameter_effects_have_multi_param_templates() {
    let lib = library();
    for e in ["move", "particles", "image-pop", "forge"] {
        let target = TargetKind::Effect(e.to_string());
        let multi = lib
            .for_target(&target)
            .filter(|l| l.tracks.iter().filter(|t| matches!(t.target, TrackTarget::Float { .. })).count() >= 2)
            .count();
        assert!(multi >= 2, "fx.{e}: {multi} multi-param templates");
    }
}

/// The value a float track holds at the start of `step` (phase 0), or `None`
/// when the loop has no such track.
fn unit_at(l: &metal_perform::pattern::Loop, param: &str, step: u32) -> Option<f32> {
    let pos = metal_perform::clock::Position::from_beats(step as f64 / 4.0);
    assert_eq!(pos.step as u32, step);
    l.tracks.iter().find_map(|t| match (&t.target, t.eval(pos)) {
        (TrackTarget::Float { param: p }, Some(metal_perform::pattern::Value::Unit(u))) if p == param => Some(u),
        _ => None,
    })
}

fn argmax(v: impl Iterator<Item = (u32, f32)>) -> u32 {
    v.fold((0, f32::MIN), |best, (i, x)| if x > best.1 { (i, x) } else { best }).0
}

/// T13: every `strobe-<pair>` fires white exactly once per bar, on the step
/// its `warp-<pair>` snaps (the biggest instant jump of `amount`, for the
/// `*-snap` pairs) or crests (the `amount` peak, for the wave pairs). All
/// loops share one clock, so the same step index is the same instant.
#[test]
fn each_strobe_lands_on_its_paired_warp_snap_or_crest() {
    let lib = library();
    let strobes: Vec<_> = lib.loops().filter(|l| l.id.starts_with("strobe-")).collect();
    assert!(strobes.len() >= 6, "the warp pack ships its strobes");
    for s in strobes {
        let pair = &s.id["strobe-".len()..];
        assert_eq!(s.target_kind, TargetKind::Effect("flash".into()), "{}", s.id);
        let warp = lib.get(&format!("warp-{pair}")).unwrap_or_else(|| panic!("{}: no warp-{pair}", s.id));
        assert_eq!(warp.target_kind, TargetKind::Effect("warp".into()));
        let opacity: Vec<f32> = (0..16).map(|i| unit_at(s, "opacity", i).expect("opacity track")).collect();
        assert_eq!(opacity.iter().filter(|&&o| o >= 0.5).count(), 1, "{}: white once per loop", s.id);
        let hit = argmax(opacity.iter().copied().enumerate().map(|(i, o)| (i as u32, o)));
        let amount: Vec<f32> = (0..16).map(|i| unit_at(warp, "amount", i).expect("amount track")).collect();
        let event = if pair.ends_with("-snap") {
            argmax((0..16u32).map(|i| (i, (amount[i as usize] - amount[(i as usize + 15) % 16]).abs())))
        } else {
            argmax(amount.iter().copied().enumerate().map(|(i, a)| (i as u32, a)))
        };
        assert_eq!(hit, event, "{} fires on step {hit}, warp-{pair} snaps/crests on {event}", s.id);
    }
    // Both directions of the radial stretch ship, easing one way and
    // snapping the other.
    for dir in ["in", "out"] {
        let w = lib.get(&format!("warp-zoom-{dir}-snap")).expect("zoom pair");
        let a: Vec<f32> = (0..16).map(|i| unit_at(w, "amount", i).unwrap()).collect();
        let jumps: Vec<f32> = (0..16).map(|i| (a[i] - a[(i + 15) % 16]).abs()).collect();
        let big = jumps.iter().cloned().fold(0.0, f32::max);
        assert!(jumps.iter().filter(|&&j| j > big * 0.5).count() == 1, "warp-zoom-{dir}-snap: one snap, the rest eased");
    }
}

/// T14: the reggaeton / dembow set — "boom-ch-boom-chic", hits on steps 4,
/// 5, 12 and 13 counted from 1, i.e. indices {3, 4, 11, 12}. Each `dembow-*`
/// template's first track is the one that hits: its above-midpoint steps
/// are exactly those four. An effect, a warp and a model template ship.
#[test]
fn dembow_templates_hit_exactly_on_3_4_11_12() {
    let lib = library();
    let set: Vec<_> = lib.loops().filter(|l| l.id.starts_with("dembow-")).collect();
    let kinds: BTreeSet<String> = set.iter().map(|l| format!("{:?}", l.target_kind)).collect();
    assert!(kinds.contains("Effect(\"warp\")"), "a warp template: {kinds:?}");
    assert!(kinds.contains("Effect(\"flash\")"), "an effect (strobe) template: {kinds:?}");
    assert!(set.iter().any(|l| matches!(l.target_kind, TargetKind::Model(_))), "a model template");
    for l in set {
        let TrackTarget::Float { param } = &l.tracks[0].target else { panic!("{}: lead is a float track", l.id) };
        let v: Vec<f32> = (0..16).map(|i| unit_at(l, param, i).expect("lead track")).collect();
        let (lo, hi) = v.iter().fold((f32::MAX, f32::MIN), |(a, b), &x| (a.min(x), b.max(x)));
        let mid = (lo + hi) / 2.0;
        let hits: BTreeSet<u32> = (0..16u32).filter(|&i| v[i as usize] > mid).collect();
        assert_eq!(hits, BTreeSet::from([3, 4, 11, 12]), "{}: hits {hits:?}", l.id);
    }
}
